{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Linezolid, the closest analogue sharing the oxazolidinone core and para-aryl morpholine, has essentially complete absolute oral bioavailability (~100%) in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Delpazolid (LCB01-0371), another oxazolidinone with a modified C5 substituent and N-aryl heterocycle, showed 99.75% absolute oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Contezolid, a more complex oxazolidinone, had an absolute bioavailability of 0.640 in healthy subjects, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "YH4808, a linezolid-like oxazolidinone with a thiomorpholine and acetyl, had low absolute bioavailability (10.1%); however, its thiomorpholine and acetyl differ from the query's morpholinone and chlorothiophene carbonyl, limiting transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "Cadazolid, an oxazolidinone-quinolone hybrid, had very low oral bioavailability, but it is designed to be nonabsorbed and is structurally distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a linezolid-type oxazolidinone. The closest analogue linezolid and other oxazolidinones (delpazolid, contezolid) show high absolute oral bioavailability (64-100%). The low-F oxazolidinone examples are less transferable (thiomorpholine/acetyl or deliberately nonabsorbed hybrid). Therefore predict high F (>=20%).",
  "evidence_gaps": [
    "No direct experimental F value for the exact query molecule.",
    "The mechanism underlying YH4808's low F is not established, so its relevance to the query's morpholinone/chlorothiophene scaffold is uncertain.",
    "No permeability, solubility, or first-pass metabolism data are available for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

